import java.io.*;
import java.util.*;

public class div25 {
    public static char[] str;
    public static int S;

    public static void main(String[] args) throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        str = in.readLine().toCharArray();
        S = str.length;
        long ans = 0;

        // Check all valid endings for divisibility by 25: 00, 25, 50, 75
        int[][] endings = {{0, 0}, {2, 5}, {5, 0}, {7, 5}};

        for (int[] ending : endings) {
            ans += countForEnding(ending[0], ending[1]);
        }

        System.out.println(ans);
    }

    static long countForEnding(int d1, int d2) {
        // d1 is the tens digit, d2 is the units digit
        // Check if the last two digits can be set to d1 and d2

        // First, check if the last two positions are compatible with d1 and d2
        if (S == 1) {
            // Special case: single digit
            if (str[0] == 'X') {
                // X must be the same digit everywhere, but we only have one digit
                // For divisibility by 25, only 0 works
                return (d1 == 0 && d2 == 0) ? 1 : 0;
            } else if (str[0] == '_') {
                return (d1 == 0 && d2 == 0) ? 1 : 0;
            } else {
                int val = str[0] - '0';
                return (val == 0 && d1 == 0 && d2 == 0) ? 1 : 0;
            }
        }

        // For numbers with at least 2 digits
        if (S < 2) return 0;

        // Check last two digits
        long ways = 1;

        // Process second last digit (tens place)
        if (str[S-2] == 'X') {
            // X must be d1
            // But we need to ensure consistency if X appears elsewhere
            // For now, just check if it's compatible
        } else if (str[S-2] != '_') {
            int val = str[S-2] - '0';
            if (val != d1) return 0;
        }

        // Process last digit (units place)
        if (str[S-1] == 'X') {
            // X must be d2
            // But if it's the same X as before, d1 must equal d2
            if (str[S-2] == 'X' && d1 != d2) return 0;
        } else if (str[S-1] != '_') {
            int val = str[S-1] - '0';
            if (val != d2) return 0;
        }

        // Now count possibilities for the remaining digits (positions 0 to S-3)
        // We need to track what value X must have if it appears
        int X_value = -1; // -1 means not determined yet

        // Determine X_value from the last two positions if X is used there
        if (str[S-2] == 'X') {
            X_value = d1;
        }
        if (str[S-1] == 'X') {
            if (X_value == -1) {
                X_value = d2;
            } else if (X_value != d2) {
                return 0; // Conflict
            }
        }

        // Now process the prefix (positions 0 to S-3)
        for (int i = 0; i < S-2; i++) {
            if (str[i] == 'X') {
                if (X_value == -1) {
                    // X is not yet determined, we'll determine it here
                    // But we need to be careful about leading zeros
                    if (i == 0) {
                        // X at the first position cannot be 0
                        // So X can be 1-9, but we'll count possibilities later
                        // For now, mark that X must be non-zero
                        X_value = 10; // special marker for "any non-zero"
                    } else {
                        X_value = 11; // special marker for "any digit"
                    }
                } else if (X_value == 10) {
                    // X was marked as non-zero, but now we're in a non-first position
                    // This is fine, X can still be non-zero
                } else if (X_value == 11) {
                    // X was marked as any digit, still fine
                } else {
                    // X_value is a specific digit, check consistency
                    if (X_value != d1 && X_value != d2) {
                        // This shouldn't happen since we only have one X value
                        // But if X appears in prefix and we already set it, it must match
                        // Actually, X_value should be consistent across all X positions
                        // So if we already have X_value set, it must match
                        // But we already set X_value from the last two positions if X was there
                        // So here we just continue
                    }
                }
            } else if (str[i] == '_') {
                // Underscore can be any digit, but first position cannot be 0
                if (i == 0) {
                    // 9 possibilities: 1-9
                    ways *= 9;
                } else {
                    // 10 possibilities: 0-9
                    ways *= 10;
                }
            } else {
                // Fixed digit, check for leading zero
                if (i == 0 && str[i] == '0') {
                    return 0; // leading zero not allowed
                }
            }
        }

        // Now handle X in the prefix
        // We need to count how many X's are in the prefix and what constraints they have
        int X_count = 0;
        for (int i = 0; i < S-2; i++) {
            if (str[i] == 'X') X_count++;
        }

        if (X_count > 0) {
            if (X_value == -1) {
                // X is only in the prefix, not in the last two positions
                // Determine X_value based on prefix constraints
                boolean first_is_X = (str[0] == 'X');
                if (first_is_X) {
                    // X at first position cannot be 0
                    ways *= 9; // 1-9
                } else {
                    ways *= 10; // 0-9
                }
            } else if (X_value == 10) {
                // X was marked as non-zero (from first position)
                ways *= 9; // 1-9
            } else if (X_value == 11) {
                // X was marked as any digit
                ways *= 10; // 0-9
            } else {
                // X_value is a specific digit, and it's consistent
                // No additional multiplication needed since X is fixed
            }
        }

        // Special case: if the entire number is just "0" or "0000" etc., that's allowed
        // But our logic should handle it: if all digits are 0, and it's a valid number
        // However, leading zeros are not allowed except for the number 0 itself
        // So if the number has length > 1 and starts with 0, it's invalid
        // We already check for leading zero in the prefix

        return ways;
    }
}
